using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class CameraProfileConfiguration:IEntityTypeConfiguration<CameraProfile>{public void Configure(EntityTypeBuilder<CameraProfile>b){b.ToTable("camera_profiles");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(100);b.Property(x=>x.CameraType).HasMaxLength(40);b.Property(x=>x.Resolution).HasMaxLength(20);b.Property(x=>x.Contrast).HasMaxLength(20);b.Property(x=>x.WhiteBalance).HasMaxLength(30);b.HasIndex(x=>new{x.OrganizationId,x.Name}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class CameraSettingsHistoryConfiguration:IEntityTypeConfiguration<CameraSettingsHistory>{public void Configure(EntityTypeBuilder<CameraSettingsHistory>b){b.ToTable("camera_settings_history");b.ConfigureBase();b.Property(x=>x.PreviousValue).HasColumnType("nvarchar(max)");b.Property(x=>x.NewValue).HasColumnType("nvarchar(max)");b.HasIndex(x=>x.OrganizationId);b.HasIndex(x=>x.CameraProfileId);b.HasIndex(x=>x.ChangedAt);b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<CameraProfile>().WithMany().HasForeignKey(x=>x.CameraProfileId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.ChangedBy).OnDelete(DeleteBehavior.Restrict);}}
